Given an array of integers, A[] of size N. For each ith element in the array, calculate the absolute difference between the count of numbers that are to the left of i and are strictly greater than the ith element, and the count of numbers that are to the right of i and are strictly lesser than the ith element.

Examples:

Input: N = 5, A[] = {5, 4, 3, 2, 1}Output: 4 2 0 2 4 Explanation: We can see that the required number for the 1st element is |0-4| = 4

Input: N = 5, A[] = {1, 2, 3, 4, 5}Output: 0 0 0 0 0Explanation: There is no greater element on the left for any element and no lesser element on the right.

Try It YourselfApproach: To solve the problem follow the below idea:

The solution to finding the absolute difference between the number of elements greater than and lesser than each element in a given array, involves using a Binary Index Tree. The approach involves sorting the array and mapping each element to its corresponding index in the sorted array, constructing two Binary Index Trees for counting the number of elements less than each element from the right side and greater than each element from the left side, respectively, and computing the absolute difference between the counts for each element.

Steps that were to follow the above approach:

Create a Binary Index Tree object with an array of size n+1 initialized with 0.Sort the given input array and create a map of the sorted array elements with their corresponding indices.Create an array of indices of the input array elements using the map created in the previous step.Create another Binary Index Tree object with an array of size n+1 initialized with 0.Traverse the array of indices from right to left and for each index,  find the number of elements smaller than the current element to its right using the Binary Index Tree created in the previous step, update the Binary Index Tree with the current index, and store the result in a separate array.Reverse the array of indices and repeat the traversal, but this time find the number of elements greater than the current element to its left.For each element in the two arrays created in the two traversals, calculate their absolute difference and store the result in a third array.Return the third array as the final result.Below is the code to implement the above steps:



            C++

    #include <iostream>
#include <vector>
#include <algorithm>
#include <unordered_map>

using namespace std;

// Binary Indexed Tree class.
class BinaryIndexTree {
private:
    vector<int> arr;

public:
    BinaryIndexTree(int size) {
        arr.resize(size + 1, 0);
    }

    void update(int x, int val) {
        if (x == 0)
            return;
        for (; x < arr.size(); x += x & -x)
            arr[x] += val;
    }

    int query(int index) {
        if (index == 0)
            return 0;
        int sum = 0;
        for (; index > 0; index -= index & -index)
            sum += arr[index];
        return sum;
    }
};

// Function to return the resultant array.
vector<int> retResult(vector<int>& arr, int n) {
    vector<int> arrSorted = arr;
    sort(arrSorted.begin(), arrSorted.end());

    unordered_map<int, int> map;
    for (int i = 0; i < arrSorted.size(); i++) {
        map[arrSorted[i]] = i + 1;
    }

    vector<int> arrIndexes(arr.size());
    int idx = 0;
    for (int key : arr) {
        arrIndexes[idx++] = map[key];
    }

    BinaryIndexTree bitRightLesser(arr.size() + 1);
    vector<int> right(n);
    for (int i = n - 1; i >= 0; i--) {
        right[i] = bitRightLesser.query(arrIndexes[i] - 1);
        bitRightLesser.update(arrIndexes[i], 1);
    }

    for (int i = 0; i < n; i++) {
        arrIndexes[i] = n + 1 - arrIndexes[i];
    }

    BinaryIndexTree bitLeftGreater(arr.size() + 1);
    vector<int> left(n);
    for (int i = 0; i < n; i++) {
        left[i] = bitLeftGreater.query(arrIndexes[i] - 1);
        bitLeftGreater.update(arrIndexes[i], 1);
    }

    vector<int> ret(n);
    for (int i = 0; i < n; i++) {
        ret[i] = abs(right[i] - left[i]);
    }

    return ret;
}

// Driver's code
int main() {
    vector<int> arr = { 5, 4, 3, 2, 1 };
    int n = arr.size();

    // Function call
    vector<int> ret = retResult(arr, n);

    cout << "[";
    for (int i = 0; i < ret.size(); i++) {
        cout << ret[i];
        if (i != ret.size() - 1)
            cout << ", ";
    }
    cout << "]" << endl;

    return 0;
}

